import { useEffect, useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<ThemeValue, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<ThemeValue>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [fontFamily, setFontFamily] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, dense, fontFamily });
  }, [theme, scale, dense, fontFamily, onChange]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', maxWidth: 480 }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h2 style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font-display)', margin: 0 }}>
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: '14px' }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => setTheme(value as ThemeValue)}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => setDense(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Sans (Inter Tight)' },
          { value: 'mono', label: 'Mono (JetBrains Mono)' },
          { value: 'display', label: 'Display (Fraunces)' },
        ]}
        value={fontFamily}
        onValueChange={setFontFamily}
      />
    </div>
  );
}

